"""Keyword classifier: SEPA product description -> (categoria, subcategoria) or None.

SEPA has no category field, so food/drinks are inferred from abbreviated descriptions.
NOT is a veto list (cleaning, hygiene, pets, hardware) checked before any match.
"""
import re
import unicodedata
def norm(s):
    return unicodedata.normalize('NFKD',s.upper()).encode('ascii','ignore').decode()
def R(words): return re.compile(r"\b(?:"+"|".join(words.split())+r")\b")
NOT=R(r"""DETERG\w* SH SHAMP\w* ACOND\w* ENJUAG\w* JAB JABON\w* DESOD\w* DEO LIMP\w* SUAVIZ\w* LAVAV\w* LAVANDINA INSEC\w* DENTAL\w* CEPILLO\w* PA[NÑ]O\w* TOALLA\w* PA[NÑ]AL\w* HIGIENICO\w* SERVILLETA\w* ESPONJA\w* ESTROPAJO BOLSA\w* BSA FILM ALUMINIO VELA\w* FOSFORO\w* ENCENDEDOR\w* PILA\w* LAMPARA\w* COLONIA OXIGENADA MASCOTA\w* PERRO\w* GATO\w* GAT PERR CACHORR\w* ARENA AROMATIZ\w* AMBIENTAL\w* ANTITRANSP\w* MAQUILL\w* ESMALTE AFEITAR PROTECTOR\w* TAMPON\w* ABSORB\w* MICELAR PISTOLA DISPENSER LIJA BIFERA TIN NUTRISSE HIDRATANTE LOCION GEL TINTURA TRAPO\w* REPASADOR VASO\w* PLATO\w* CUBIERT\w* ESCOBA BALDE TAPABOCA\w* LUBRIC\w* MOTOR ANTICONGEL\w* FRENO PARABRISAS PELADOR ABRELATAS BATERIA CAFETERA TERMO BOMBILLA YERBERA JARRA COPA CARBON LE[NÑ]A DOVE ELVIVE REXONA NIVEA COLGATE SEDAL PANTENE GLADE AYUDIN CIF PLUSBELLE SAMSUNG PHILIPS REMERA ROPA CELULAR\w* SHORT SOLAR BRILLO PLAYERA TEX TOCADOR ALGABO COLORACION LED CEL KIT PERFUME\w* ALIM ALIMENTO BEBE BABY CORPORAL FACIAL PIEL CABELLO CAPILAR\w* ROPA INTERIOR MEDIA\w* ZAPATILLA\w* SANDALIA\w* TV SMART NOTEBOOK TABLET AURICULAR\w* CABLE\w* CARGADOR\w* ACEITE\w*\ (MOTOR|LUBR\w*)""")
# note: ALIM/ALIMENTO vetoed (pet food / baby); comidas never start with that in SEPA abbreviations
BEB=[('Cervezas',r"CERVEZ\w* IPA STOUT LAGER QUILMES BRAHMA STELLA\ ARTOIS CORONA HEINEKEN SCHNEIDER BUDWEISER ISENBECK WARSTEINER MALTA"),
 ('Vinos y espumantes',r"VINO\w* MALBEC CABERNET TORRONTES CHARDONNAY SYRAH MERLOT PINOT BONARDA TEMPRANILLO ESPUMANTE CHAMPAGNE CHAMPA[NG]\w* SIDRA SANGRIA CHANDON TRAPICHE"),
 ('Aperitivos y destilados',r"FERNET BRANCA CINZANO GANCIA APEROL CAMPARI WHISKY WHISKEY VODKA GIN RON LICOR\w* TEQUILA AMARETTO BAILEYS COGNAC BRANDY APERITIVO VERMOUTH VERMUT"),
 ('Gaseosas y jugos',r"GASEOS\w* COCA(?:[-\ ]?COLA)? SPRITE FANTA PEPSI SEVEN\ ?UP 7UP MIRINDA PASO\ DE\ LOS\ TOROS SCHWEPPES TONICA MANAOS CUNNINGTON SODA SIFON\w* MONSTER RED\ BULL ENERGIZ\w* ISOTONIC\w* GATORADE POWERADE LEVITE BAGGIO CEPITA TANG REFRESC\w* JUGO\w* NECTAR LIMONADA"),
 ('Aguas',r"AGUA AGUAS VILLAVICENCIO BONAQUA AQUAFINA"),
 ('Infusiones',r"CAFE CAFES YERBA\w* TE MATE\ COCIDO CAPUCCINO CAPUCHINO MANZANILLA BOLDO TILO POLEO ROOIBOS TARAGUI PLAYADITO ROSAMONTE NESCAFE DOLCA SAQ\w* CHOCOLATADA NESQUIK"),
]
FOOD=[('Lácteos y huevos',r"LECHE\w* YOGUR\w* YOGHURT YOGURT QUESO\w* MANTECA MARGARINA CREMA\ DE\ LECHE RICOTA MUZZARELLA MUZARELLA MOZZARELLA CASANCREM PARMESANO SARDO CREMOSO PORT\ SALUT HUEVO\w* FLAN POSTRE\w* PUDDING PUDIN DANETTE SERENISIMA SANCOR ILOLAY MILKAUT PROVOLONE KEFIR UNTABLE CHEDDAR RALLAD\w*"),
 ('Carnes, pescados y fiambres',r"CARNE\w* BIFE\w* ASADO VACIO MILANESA\w* HAMBURGUES\w* CHORIZO\w* SALCHICH\w* MORCILLA POLLO\w* PECHUGA MUSLO SUPREMA CERDO BONDIOLA PANCETA JAMON\w* SALAME\w* SALAMIN FIAMBRE\w* MORTADELA PATE LOMO LOMITO PALETA PICADA MATAMBRE COSTILLA PECETO NALGA CUADRIL COLITA ENTRA[NÑ]A OSOBUCO CHURRASCO TERNERA CORDERO PAVO PESCADO\w* MERLUZA ATUN SARDINA\w* CABALLA SALMON CALAMAR\w* CAMARON\w* LANGOSTINO\w* SURIMI PRESUNTO BACON NUGGET\w* PATY ROAST\ BEEF"),
 ('Frutas y verduras',r"MANZANA\w* PERA PERAS BANANA\w* NARANJA\w* MANDARINA\w* LIMON\w* POMELO\w* FRUTILLA\w* DURAZNO\w* CIRUELA\w* UVA\w* SANDIA MELON ANANA KIWI PALTA MANGO PAPA PAPAS BATATA ZANAHORIA CEBOLLA\w* TOMATE\w* LECHUGA ESPINACA ACELGA ZAPALLO ZAPALLITO CALABAZA PIMIENTO MORRON AJO AJOS BROCOLI COLIFLOR REPOLLO CHAUCHA\w* CHOCLO PEPINO BERENJENA APIO PUERRO RUCULA HONGO\w* CHAMPI[NÑ]ON\w* VERDURA\w* VERDEO PEREJIL ALBAHACA FRUTA\w* ENSALADA\w* ARANDANO\w* CEREZA\w* HIGO\w* DAMASCO\w* PASAS REMOLACHA MAIZ ARVEJA\w* LENTEJA\w* GARBANZO\w* POROTO\w* ACEITUNA\w* PEPINILLO\w* JARDINERA MACEDONIA PURE\ DE\ (?:TOMATE|PAPA\w*)"),
 ('Panificados y galletitas',r"PAN PANES PANCITO\w* MIGNON FACTURA\w* MEDIALUNA\w* CROISSANT TOSTADA\w* GALLET\w* CRACKER\w* BIZCOCH\w* BUDIN MAGDALENA\w* MADALENA\w* ALFAJOR\w* TORTA\w* TORTILLA\w* WRAP PIZZA\w* PREPIZZA EMPANADA\w* TARTA\w* BROWNIE\w* GRISSINI\w* GRISINES SCONE\w* PAN\ DULCE PANETTONE ROSCA TURRON\w* BARQUILLO\w* OBLEA\w* HARINA\w* SEMOLA POLENTA ALMIDON LEVADURA PAN\ RALLADO REBOZADOR PRE\ MEZCLA PREMEZCLA"),
 ('Pastas, arroz y cereales',r"FIDEO\w* FIDEOS TALLARIN\w* ESPAGUETI\w* SPAGHETTI MOSTACCIOL\w* TIRABUZ\w* RAVIOL\w* SORRENTINO\w* [ÑN]OQUI\w* CAPELETINI\w* CANELON\w* LASA[NÑ]A PASTA\w* PENNE RIGATONI ARROZ AVENA CEREAL\w* GRANOLA MUESLI QUINOA COUSCOUS COPOS CORN\ FLAKES SOPA\w* CALDO\w* SALSA\w* ADEREZO\w* MAYONESA KETCHUP MOSTAZA CHIMICHURRI VINAGRE ACEITE ACEITE\w* SAL PIMIENTA PIMENTON COMINO CURCUMA OREGANO CONDIMENTO\w* ESPECIA\w*"),
 ('Dulces, golosinas y snacks',r"AZUCAR ENDULZANTE EDULCORANTE EDULCO STEVIA MIEL DULCE\w* MERMELADA\w* MERM JALEA CHOCOLATE\w* BOMBON\w* BOMBONES CARAMELO\w* GOLOSINA\w* CHICLE\w* GOMITA\w* MALVAVISCO\w* CHUPETIN\w* MANI SNACK\w* PAPAS\ FRITAS PALITOS CHIZITOS NACHOS POCHOCLO\w* FRUTOS\ SECOS ALMENDRA\w* NUECES AVELLANA\w* PISTACHO\w* HELADO\w* GELATINA\w* MEMBRILLO OREO PEPITOS CACAO CHOCOLATIN\w* ALFAJORES BARRA\w* TOBLERON\w*"),
]
BEBR=[(k,R(v)) for k,v in BEB]; FOODR=[(k,R(v)) for k,v in FOOD]
def cls(desc):
    d=norm(desc)
    if NOT.search(d): return None
    for k,r in BEBR:
        if r.search(d): return ('Bebidas',k)
    for k,r in FOODR:
        if r.search(d): return ('Comidas',k)
    return None
